public class FanoutService {
  private static final int CELEBRITY_THRESHOLD = 100_000;
  private static final int TIMELINE_CAP = 1000;
  private final GraphStore graph; private final TimelineStore timelines;
  private final CelebrityIndex celebrities; private final Queue fanoutQueue;

  // Write path: persist already done, now decide push vs skip.
  public void onPostCreated(Post post) {
    long followers = graph.followerCount(post.authorId());
    if (followers > CELEBRITY_THRESHOLD || celebrities.isCelebrity(post.authorId())) {
      celebrities.indexPost(post); // pull path only, no fanout
      return;
    }
    // Page followers to bound memory; each page becomes a job.
    String cursor = null;
    do {
      FollowPage page = graph.listFollowers(post.authorId(), cursor, 1000);
      fanoutQueue.publish(new FanoutJob(post.postId(), post.createdAt(), page.ids()));
      cursor = page.nextCursor();
    } while (cursor != null);
  }

  public void applyFanout(FanoutJob job) {
    for (long followerId : job.followerIds()) {
      timelines.prepend(followerId, job.postId(), job.createdAt(), TIMELINE_CAP);
    }
  }
}
